from __future__ import annotations

from dataclasses import dataclass, field

from shop import discounts, tax
from shop.money import Money, total


@dataclass
class CartLine:
    sku: str
    unit_price: Money
    quantity: int
    category: str = "general"

    def amount(self) -> Money:
        return self.unit_price.times(self.quantity)


@dataclass
class Cart:
    region: str
    lines: list[CartLine] = field(default_factory=list)
    discount: discounts.Discount | None = None

    def add(self, sku: str, price: Money, quantity: int = 1, category: str = "general") -> None:
        for line in self.lines:
            if line.sku == sku:
                line.quantity += quantity
                return
        self.lines.append(CartLine(sku, price, quantity, category))

    def remove(self, sku: str) -> None:
        self.lines = [line for line in self.lines if line.sku != sku]

    def subtotal(self) -> Money:
        return total([line.amount() for line in self.lines])

    def discounted(self) -> Money:
        subtotal = self.subtotal()
        return discounts.apply(subtotal, self.discount) if self.discount else subtotal


@dataclass(frozen=True)
class Checkout:
    subtotal: Money
    discounted: Money
    tax: Money
    total: Money


def checkout_total(cart: Cart) -> Checkout:
    subtotal = cart.subtotal()
    discounted = cart.discounted()
    vat = tax.compute_tax(cart.lines, cart.region)
    rule = tax.rule_for(cart.region)
    grand = discounted if rule.inclusive else discounted + vat
    return Checkout(subtotal, discounted, vat, grand)


def receipt_lines(cart: Cart) -> list[str]:
    result = checkout_total(cart)
    rows = [f"{line.sku} x{line.quantity} {line.amount().as_text()}" for line in cart.lines]
    rows.append(f"Subtotal {result.subtotal.as_text()}")
    if result.discounted != result.subtotal:
        rows.append(f"After discount {result.discounted.as_text()}")
    rows.append(f"VAT {result.tax.as_text()}")
    rows.append(f"Total {result.total.as_text()}")
    return rows
