from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal

from shop.money import Money


@dataclass(frozen=True)
class TaxRule:
    region: str
    rate: Decimal
    inclusive: bool = False
    exempt_categories: tuple[str, ...] = ()


RULES = {
    "ZA": TaxRule("ZA", Decimal("0.15"), inclusive=True, exempt_categories=("basic-food",)),
    "NA": TaxRule("NA", Decimal("0.15")),
    "BW": TaxRule("BW", Decimal("0.14")),
    "KE": TaxRule("KE", Decimal("0.16"), exempt_categories=("medicine",)),
}


def rule_for(region: str) -> TaxRule:
    try:
        return RULES[region]
    except KeyError:
        raise ValueError(f"no tax rule for region {region}") from None


def line_tax(price: Money, quantity: int, category: str, rule: TaxRule) -> Money:
    if category in rule.exempt_categories:
        return Money(0, price.currency)
    gross = price.times(quantity)
    if rule.inclusive:
        # Tax already inside the price: tax = gross - gross / (1 + rate)
        net = Money(int(Decimal(gross.minor) / (1 + rule.rate)), gross.currency)
        return gross - net
    return gross.scaled(rule.rate)


def compute_tax(lines, region: str) -> Money:
    rule = rule_for(region)
    tax = Money(0)
    for line in lines:
        tax = tax + line_tax(line.unit_price, line.quantity, line.category, rule)
    return tax


def describe(region: str) -> str:
    rule = rule_for(region)
    kind = "inclusive" if rule.inclusive else "added"
    return f"{rule.region}: {rule.rate * 100}% {kind}"
