from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal, ROUND_HALF_UP


@dataclass(frozen=True)
class Money:
    minor: int
    currency: str = "ZAR"

    @classmethod
    def from_decimal(cls, value: Decimal, currency: str = "ZAR") -> "Money":
        return cls(int((value * 100).quantize(Decimal("1"), rounding=ROUND_HALF_UP)), currency)

    def __add__(self, other: "Money") -> "Money":
        self._same(other)
        return Money(self.minor + other.minor, self.currency)

    def __sub__(self, other: "Money") -> "Money":
        self._same(other)
        return Money(self.minor - other.minor, self.currency)

    def times(self, quantity: int) -> "Money":
        return Money(self.minor * quantity, self.currency)

    def scaled(self, rate: Decimal) -> "Money":
        exact = Decimal(self.minor) * rate
        return Money(int(exact.quantize(Decimal("1"), rounding=ROUND_HALF_UP)), self.currency)

    def _same(self, other: "Money") -> None:
        if other.currency != self.currency:
            raise ValueError(f"currency mismatch: {self.currency} != {other.currency}")

    def as_text(self) -> str:
        sign = "-" if self.minor < 0 else ""
        whole, cents = divmod(abs(self.minor), 100)
        return f"{sign}{self.currency} {whole}.{cents:02d}"


ZERO = Money(0)


def total(values: list[Money]) -> Money:
    result = ZERO
    for value in values:
        result = result + value
    return result
