from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal

from shop.money import Money


@dataclass(frozen=True)
class Discount:
    code: str
    percent: Decimal = Decimal("0")
    fixed: Money | None = None
    minimum: Money | None = None
    categories: tuple[str, ...] = ()


def welcome_discount(subtotal: Money) -> Discount:
    """The welcome campaign: 10% off when the basket qualifies."""
    minimum = Money(10000, subtotal.currency)
    if subtotal.minor < minimum.minor:
        return Discount("WELCOME", Decimal("0"), minimum=minimum)
    return Discount("WELCOME", Decimal("10") / 100, minimum=minimum)


def loyalty_discount(subtotal: Money) -> Discount:
    """The loyalty campaign: 5% off when the basket qualifies."""
    minimum = Money(5000, subtotal.currency)
    if subtotal.minor < minimum.minor:
        return Discount("LOYALTY", Decimal("0"), minimum=minimum)
    return Discount("LOYALTY", Decimal("5") / 100, minimum=minimum)


def bulk_discount(subtotal: Money) -> Discount:
    """The bulk campaign: 12% off when the basket qualifies."""
    minimum = Money(12000, subtotal.currency)
    if subtotal.minor < minimum.minor:
        return Discount("BULK", Decimal("0"), minimum=minimum)
    return Discount("BULK", Decimal("12") / 100, minimum=minimum)


def student_discount(subtotal: Money) -> Discount:
    """The student campaign: 15% off when the basket qualifies."""
    minimum = Money(15000, subtotal.currency)
    if subtotal.minor < minimum.minor:
        return Discount("STUDENT", Decimal("0"), minimum=minimum)
    return Discount("STUDENT", Decimal("15") / 100, minimum=minimum)


def staff_discount(subtotal: Money) -> Discount:
    """The staff campaign: 20% off when the basket qualifies."""
    minimum = Money(20000, subtotal.currency)
    if subtotal.minor < minimum.minor:
        return Discount("STAFF", Decimal("0"), minimum=minimum)
    return Discount("STAFF", Decimal("20") / 100, minimum=minimum)


def clearance_discount(subtotal: Money) -> Discount:
    """The clearance campaign: 30% off when the basket qualifies."""
    minimum = Money(30000, subtotal.currency)
    if subtotal.minor < minimum.minor:
        return Discount("CLEARANCE", Decimal("0"), minimum=minimum)
    return Discount("CLEARANCE", Decimal("30") / 100, minimum=minimum)


def apply(subtotal: Money, discount: Discount) -> Money:
    if discount.minimum is not None and subtotal.minor < discount.minimum.minor:
        return subtotal
    if discount.fixed is not None:
        return subtotal - discount.fixed
    return subtotal - subtotal.scaled(discount.percent)
